     1|/**
     2| * IVX Senior-Developer Answer Format
     3| *
     4| * Renders the senior-developer runtime proof into the OWNER-REQUIRED strict
     5| * execution format. The owner explicitly rejected narrative prose
     6| * ("TASK UNDERSTOOD / FILES INSPECTED / ...") and the old 8-section layout.
     7| *
     8| * Every development task must return ONLY the 6 evidence sections:
     9| *
    10| *   TASK ID
    11| *   STATUS
    12| *   FILES CHANGED
    13| *   COMMANDS
    14| *   TESTS
    15| *   DEPLOYED PROOF
    16| *
    17| * Hard enforcement (no claims without real commands):
    18| *   - No files changed      -> "NO CODE CHANGED — no development was completed."
    19| *   - No tests run          -> "NOT VERIFIED — tests were not run."
    20| *   - Patch could not write -> "BLOCKED — I do not have code write access."
    21| *
    22| * CRITICAL: the user's goal text is NEVER echoed into the answer. Copying the
    23| * goal into the response caused the Fake Execution Guard to false-positive on
    24| * innocent words like "complete" ("complete the loading on this chat") and
    25| * replace a real DEPLOYED answer with a generic BLOCKED message.
    26| *
    27| * 2026-07-20 completion-validator integration: the status line is now decided
    28| * by the completion validator, not by simple health/commit checks. A deploy-only
    29| * redeploy with NO code change is reported as DEPLOYED_ONLY (redeployed unchanged
    30| * code — the requested fix was NOT implemented), not as DEPLOYED. A code/ui/feature
    31| * task with no code change and no deployment is reported as NOT_COMPLETED.
    32| *
    33| * This module is runtime-free and deterministic (no network/filesystem/AI) so it
    34| * is fully unit-testable.
    35| */
    36|import type { IVXSeniorDeveloperRunProof } from './ivx-senior-developer-runtime';
    37|import type { IVXOwnerExecutionDecision } from './ivx-owner-execution-mode';
    38|import type { IVXWorkerJob, IVXWorkerJobResult } from './ivx-senior-developer-worker';
    39|import {
    40|  classifyTaskType,
    41|  validateCompletion,
    42|  renderValidatorVerdict,
    43|  renderValidatorReason,
    44|  type IVXCompletionEvidence,
    45|  type IVXTaskType,
    46|  type IVXValidationVerdict,
    47|} from './ivx-completion-validator';
    48|import {
    49|  buildSeniorDeveloperNarrative,
    50|  detectForbiddenVaguePhrases,
    51|  detectInventedActions,
    52|} from './ivx-senior-developer-narrative';
    53|
    54|function trimmed(value: unknown): string {
    55|  return typeof value === 'string' ? value.trim() : '';
    56|}
    57|
    58|/** Render one validation result as raw, copy-pasteable terminal output. */
    59|function rawValidationOutput(validation: IVXSeniorDeveloperRunProof['validations'][number]): string {
    60|  return [
    61|    `$ ${validation.command}`,
    62|    validation.stdoutTail ? validation.stdoutTail.trimEnd() : '',
    63|    validation.stderrTail ? validation.stderrTail.trimEnd() : '',
    64|    validation.error ? `error: ${validation.error}` : '',
    65|    `exit code: ${validation.exitCode ?? 'null'} -> ${validation.ok ? 'PASS' : 'FAIL'}`,
    66|  ]
    67|    .filter((line) => line.length > 0)
    68|    .join('\n');
    69|}
    70|
    71|export function isTypecheckCommand(command: string): boolean {
    72|  return /\b(tsc|typecheck|type-check|type\s+check)\b/i.test(command);
    73|}
    74|
    75|export function isTestCommand(command: string): boolean {
    76|  return /\btest\b/i.test(command) && !isTypecheckCommand(command);
    77|}
    78|
    79|function buildEvidenceFromProof(proof: IVXSeniorDeveloperRunProof): IVXCompletionEvidence {
    80|  const validations = proof.validations;
    81|  const testValidations = validations.filter((v) => isTestCommand(v.command));
    82|  const typecheckValidations = validations.filter((v) => isTypecheckCommand(v.command));
    83|  const commitSha = proof.gitDeployOperator.github.commitSha;
    84|  const healthOk = proof.productionVerification.ok;
    85|  const commitMatch = healthOk && proof.changedRouteVerification.ok;
    86|  return {
    87|    taskType: classifyTaskType(proof.goal),
    88|    requestedOutcome: proof.goal.slice(0, 400),
    89|    acceptanceCriteria: [],
    90|    state: 'DEPLOYED',
    91|    previousVerdict: proof.endToEndProductionComplete ? 'VERIFIED' : null,
    92|    filesChanged: proof.changedFiles,
    93|    testsPassed: testValidations.length > 0 && validations.every((v) => v.ok),
    94|    testsRun: testValidations.length > 0,
    95|    typecheckPassed: typecheckValidations.length > 0 && validations.every((v) => v.ok),
    96|    typecheckRun: typecheckValidations.length > 0,
    97|    buildPassed: validations.length > 0 && validations.every((v) => v.ok),
    98|    buildRun: validations.length > 0,
    99|    commitSha,
   100|    deployId: proof.gitDeployOperator.render.deployId,
   101|    productionHealthOk: healthOk,
   102|    commitMatch,
   103|    featureVerificationOk: null,
   104|    error: proof.ok ? null : (proof.gitDeployOperator.reason || proof.productionVerification.error || 'Run did not complete end-to-end.'),
   105|    startedAt: proof.generatedAt,
   106|    completedAt: proof.generatedAt,
   107|    verifiedAt: proof.generatedAt,
   108|  };
   109|}
   110|
   111|function buildEvidenceFromWorkerResult(result: IVXWorkerJobResult): IVXCompletionEvidence {
   112|  return {
   113|    taskType: result.taskType ?? classifyTaskType(result.goal),
   114|    requestedOutcome: result.goal.slice(0, 400),
   115|    acceptanceCriteria: [],
   116|    state: 'DEPLOYED',
   117|    previousVerdict: result.finalStatus === 'COMPLETE' ? 'VERIFIED' : null,
   118|    filesChanged: result.changedFiles,
   119|    testsPassed: result.testsPassed,
   120|    testsRun: result.testsRun,
   121|    typecheckPassed: result.typecheckRun && result.testsPassed,
   122|    typecheckRun: result.typecheckRun,
   123|    buildPassed: result.buildRun,
   124|    buildRun: result.buildRun,
   125|    commitSha: result.commitSha,
   126|    deployId: result.deployId,
   127|    productionHealthOk: result.healthOk,
   128|    commitMatch: result.commitMatch,
   129|    featureVerificationOk: null,
   130|    error: result.error,
   131|    startedAt: result.generatedAt,
   132|    completedAt: result.generatedAt,
   133|    verifiedAt: result.generatedAt,
   134|  };
   135|}
   136|
   137|function buildFilesChangedLine(
   138|  changedFiles: string[],
   139|  patchStatus: IVXSeniorDeveloperRunProof['patchProposal']['status'],
   140|  taskType: IVXTaskType,
   141|): string {
   142|  if (changedFiles.length > 0) {
   143|    return changedFiles.map((filePath) => `- ${filePath}`).join('\n');
   144|  }
   145|  if (patchStatus === 'blocked') {
   146|    return 'BLOCKED — I do not have code write access.';
   147|  }
   148|  return `NO CODE CHANGED — no development was completed. (task type: ${taskType})`;
   149|}
   150|
   151|function buildCommandsSection(proof: IVXSeniorDeveloperRunProof): string {
   152|  const validations = proof.validations;
   153|  const commands: string[] = [];
   154|
   155|  for (const validation of validations) {
   156|    commands.push(`- $ ${validation.command} -> exit ${validation.exitCode ?? 'null'} (${validation.ok ? 'PASS' : 'FAIL'})`);
   157|  }
   158|
   159|  const git = proof.gitDeployOperator;
   160|  if (git.github.commitAttempted) {
   161|    commands.push(
   162|      `- $ git commit/push -> ${git.github.commitSha ? `exit 0 (committed ${git.github.commitSha})` : `not completed (${git.reason})`}`,
   163|    );
   164|  }
   165|  if (git.render.deployAttempted) {
   166|    commands.push(
   167|      `- $ render deploy -> ${git.render.deployId ? `exit 0 (${git.render.deployStatus ?? 'triggered'} ${git.render.deployId})` : `not completed (${git.render.error ?? git.reason})`}`,
   168|    );
   169|  }
   170|  if (proof.productionVerification.ok) {
   171|    commands.push('- $ curl /health -> exit 0 (200 healthy)');
   172|  }
   173|
   174|  return commands.length > 0 ? commands.join('\n') : 'NONE — no commands were executed.';
   175|}
   176|
   177|function buildTestsSection(proof: IVXSeniorDeveloperRunProof): string {
   178|  const testValidations = proof.validations.filter((v) => isTestCommand(v.command));
   179|  return testValidations.length > 0
   180|    ? testValidations.map(rawValidationOutput).join('\n\n')
   181|    : 'NOT VERIFIED — tests were not run.';
   182|}
   183|
   184|function buildDeployedProofSection(
   185|  proof: IVXSeniorDeveloperRunProof,
   186|  validationStatus: string,
   187|): string {
   188|  const changedFiles = proof.changedFiles;
   189|  const git = proof.gitDeployOperator;
   190|  const lines: string[] = [];
   191|
   192|  if (changedFiles.length > 0) {
   193|    lines.push('git diff --stat (applied patch):');
   194|    for (const filePath of changedFiles) {
   195|      const op = proof.patchProposal.operations.find((operation) => operation.path === filePath);
   196|      lines.push(` ${filePath} | ${op ? op.summary : 'modified'}`);
   197|    }
   198|    lines.push('git status --short:');
   199|    for (const filePath of changedFiles) {
   200|      lines.push(` M ${filePath}`);
   201|    }
   202|    if (git.github.commitSha) {
   203|      lines.push(`commit: ${git.github.commitSha}${git.github.branch ? ` (${git.github.branch})` : ''}`);
   204|    }
   205|    lines.push(
   206|      `production /health: ${proof.productionVerification.ok ? 'healthy' : 'not confirmed'}; changed route: ${proof.changedRouteVerification.ok ? 'live' : 'not confirmed'}`,
   207|    );
   208|  } else {
   209|    lines.push('git diff --stat: (no changes)');
   210|    lines.push('git status --short: (clean)');
   211|    if (git.render.deployAttempted && git.github.commitSha) {
   212|      lines.push(`deploy-only from commit: ${git.github.commitSha}${git.github.branch ? ` (${git.github.branch})` : ''}`);
   213|    }
   214|  }
   215|
   216|  if (git.render.deployId) {
   217|    lines.push(`deploy: ${git.render.deployId} (${git.render.deployStatus ?? 'unknown'})`);
   218|  }
   219|  if (validationStatus === 'NOT_COMPLETED' || validationStatus === 'NO_CHANGE_REQUIRED' || validationStatus === 'DEPLOYED_ONLY') {
   220|    lines.push(`completion verdict: ${validationStatus}`);
   221|  }
   222|  lines.push(`job: ${proof.jobId}`);
   223|
   224|  return lines.join('\n');
   225|}
   226|
   227|/**
   228| * Build the senior-developer execution answer in the owner-required 6-section
   229| * format. No goal text is echoed; only taskId, status, real files, real commands,
   230| * real tests, and real deployed proof are returned.
   231| */
   232|export function buildSeniorDeveloperExecutionAnswer(
   233|  proof: IVXSeniorDeveloperRunProof,
   234|  decision: IVXOwnerExecutionDecision,
   235|): string {
   236|  if (decision.requiresApproval) {
   237|    return [
   238|      `TASK ID:\n${proof.jobId}`,
   239|      'STATUS:\nBLOCKED',
   240|      'FILES CHANGED:\n(none — requires owner confirmation before execution)',
   241|      'COMMANDS:\nNONE — guarded action halted before repo inspection.',
   242|      'TESTS:\nNOT VERIFIED — tests were not run.',
   243|      'DEPLOYED PROOF:\nNONE — owner confirmation required.',
   244|    ].join('\n\n');
   245|  }
   246|
   247|  const changedFiles = proof.changedFiles;
   248|  const taskType = classifyTaskType(proof.goal);
   249|
   250|  if (proof.patchProposal.status === 'blocked') {
   251|    return [
   252|      `TASK ID:\n${proof.jobId}`,
   253|      'STATUS:\nBLOCKED',
   254|      `FILES CHANGED:\n${buildFilesChangedLine(changedFiles, proof.patchProposal.status, taskType)}`,
   255|      `COMMANDS:\n${buildCommandsSection(proof)}`,
   256|      `TESTS:\n${buildTestsSection(proof)}`,
   257|      `DEPLOYED PROOF:\n${buildDeployedProofSection(proof, 'BLOCKED')}`,
   258|    ].join('\n\n');
   259|  }
   260|
   261|  const validation = validateCompletion(buildEvidenceFromProof(proof));
   262|  const validatedStatus = renderValidatorVerdict(validation.verdict);
   263|  const status = validation.ok ? 'VERIFIED' : validatedStatus;
   264|
   265|  return [
   266|    `TASK ID:\n${proof.jobId}`,
   267|    `STATUS:\n${status}`,
   268|    `FILES CHANGED:\n${buildFilesChangedLine(changedFiles, proof.patchProposal.status, taskType)}`,
   269|    `COMMANDS:\n${buildCommandsSection(proof)}`,
   270|    `TESTS:\n${buildTestsSection(proof)}`,
   271|    `DEPLOYED PROOF:\n${buildDeployedProofSection(proof, status)}`,
   272|    buildNarrativeAppendix({ ...proof, executionRecord: undefined } as unknown as IVXWorkerJobResult, validation.verdict),
   273|  ].filter((section) => section.length > 0).join('\n\n');
   274|}
   275|
   276|function buildWorkerFilesChangedLine(result: IVXWorkerJobResult, taskType: IVXTaskType): string {
   277|  if (result.changedFiles.length > 0) {
   278|    return result.changedFiles.map((filePath) => `- ${filePath}`).join('\n');
   279|  }
   280|  if (result.finalStatus === 'BLOCKED') {
   281|    return 'BLOCKED — I do not have code write access.';
   282|  }
   283|  return `NO CODE CHANGED — no development was completed. (task type: ${taskType})`;
   284|}
   285|
   286|function buildWorkerCommandsSection(job: IVXWorkerJob, result: IVXWorkerJobResult): string {
   287|  const commands: string[] = [];
   288|  if (result.commitCreated) {
   289|    const exit = result.commitSha ? 0 : 1;
   290|    commands.push(
   291|      `- $ git commit/push -> exit ${exit} (${result.commitSha ? `committed ${result.commitSha.slice(0, 12)}` : 'attempted (no sha)'})`,
   292|    );
   293|  }
   294|  if (result.deployId) {
   295|    const exit = result.deployStatus === 'live' ? 0 : 1;
   296|    commands.push(
   297|      `- $ render deploy -> exit ${exit} (${result.deployStatus ?? 'triggered'} ${result.deployId})`,
   298|    );
   299|  }
   300|  if (result.testsRun) {
   301|    commands.push(`- $ bun test -> exit ${result.testsPassed ? 0 : 1} (${result.testsPassed ? 'PASS' : 'FAIL'})`);
   302|  }
   303|  if (result.typecheckRun) {
   304|    const typecheckPass = result.testsPassed;
   305|    commands.push(`- $ tsc --noEmit -> exit ${typecheckPass ? 0 : 1} (${typecheckPass ? 'PASS' : 'errors'})`);
   306|  }
   307|  if (result.healthOk) {
   308|    commands.push('- $ curl /health -> exit 0 (200 healthy)');
   309|  }
   310|  if (job.status !== 'completed' && job.status !== 'failed' && job.status !== 'blocked') {
   311|    commands.push(`- $ worker phase ${job.stage} -> exit pending (stage: ${job.stage}, progress: ${job.progressPercent}%)`);
   312|  }
   313|  return commands.length > 0 ? commands.join('\n') : 'NONE — no commands were executed.';
   314|}
   315|
   316|function buildWorkerTestsSection(result: IVXWorkerJobResult): string {
   317|  if (!result.testsRun) {
   318|    return 'NOT VERIFIED — tests were not run.';
   319|  }
   320|  return result.testsPassed
   321|    ? '$ bun test\nexit code: 0 -> PASS'
   322|    : '$ bun test\nexit code: 1 -> FAIL';
   323|}
   324|
   325|function buildWorkerDeployedProofSection(
   326|  job: IVXWorkerJob,
   327|  result: IVXWorkerJobResult,
   328|  validationStatus: string,
   329|): string {
   330|  const lines: string[] = [];
   331|  if (result.changedFiles.length > 0) {
   332|    lines.push('git diff --stat (applied patch):');
   333|    for (const filePath of result.changedFiles) {
   334|      lines.push(` ${filePath} | modified`);
   335|    }
   336|  } else {
   337|    lines.push('git diff --stat: (no changes)');
   338|  }
   339|  if (result.commitSha) {
   340|    lines.push(`commit: ${result.commitSha}${result.branch ? ` (${result.branch})` : ''}`);
   341|  }
   342|  if (result.deployId) {
   343|    lines.push(`deploy: ${result.deployId} (${result.deployStatus ?? 'unknown'})`);
   344|  }
   345|  lines.push(`production /health: ${result.healthOk ? 'healthy' : 'not confirmed'}; commit match: ${result.commitMatch ? 'true' : 'false'}`);
   346|  if (validationStatus === 'NOT_COMPLETED' || validationStatus === 'NO_CHANGE_REQUIRED' || validationStatus === 'DEPLOYED_ONLY') {
   347|    lines.push(`completion verdict: ${validationStatus}`);
   348|  }
   349|  if (result.taskState) {
   350|    lines.push(`task state: ${result.taskState}`);
   351|  }
   352|  if (result.evidenceFingerprint) {
   353|    lines.push(`evidence fingerprint: ${result.evidenceFingerprint.slice(0, 40)}`);
   354|  }
   355|  if (result.error) {
   356|    lines.push(`error: ${result.error}`);
   357|  }
   358|  lines.push(`job: ${job.jobId}`);
   359|  return lines.join('\n');
   360|}
   361|
   362|/**
   363| * Phase 7 + 10: build the 7-section narrative from the execution record (when
   364| * present) and append it to the 6-section owner-mandated format. The narrative
   365| * is the SEPARATE response engine output — it reads the record and explains
   366| * the result, separating facts from assumptions and reporting failures
   367| * honestly. Forbidden vague phrases and invented actions are detected and
   368| * flagged at the end so the owner can see the honesty guard fired.
   369| */
   370|function buildNarrativeAppendix(result: IVXWorkerJobResult, verdict: IVXValidationVerdict): string {
   371|  if (!result.executionRecord) return '';
   372|  const verdictReason = renderValidatorReason(verdict, []);
   373|  const narrative = buildSeniorDeveloperNarrative({
   374|    record: result.executionRecord,
   375|    verdict,
   376|    verdictReason,
   377|  });
   378|  const flags: string[] = [];
   379|  if (narrative.forbiddenPhrasesDetected.length > 0) {
   380|    flags.push(`forbidden-vague-phrases: ${narrative.forbiddenPhrasesDetected.join(', ')}`);
   381|  }
   382|  if (narrative.inventedActionsDetected.length > 0) {
   383|    flags.push(`invented-actions: ${narrative.inventedActionsDetected.join('; ')}`);
   384|  }
   385|  const flagLine = flags.length > 0 ? `\n\nHONESTY GUARD:\n${flags.join('\n')}` : '';
   386|  return `\n\n---\n\nNARRATIVE (7-section response engine):\n${narrative.text}${flagLine}`;
   387|}
   388|
   389|/**
   390| * Build the strict execution answer from a completed worker-queue job result.
   391| *
   392| * This is the chat-side renderer for jobs created via the persistent worker
   393| * queue. It mirrors the runtime-proof renderer above but reads from the
   394| * secret-safe IVXWorkerJobResult summary that the worker writes to the durable
   395| * proof ledger. It never fabricates evidence.
   396| */
   397|export function buildSeniorDeveloperWorkerJobAnswer(
   398|  job: IVXWorkerJob,
   399|  decision: IVXOwnerExecutionDecision,
   400|): string {
   401|  const result = job.result;
   402|  const guarded = decision.requiresApproval;
   403|
   404|  // Guarded action: blocked before execution, require owner confirmation.
   405|  if (guarded) {
   406|    return [
   407|      `TASK ID:\n${job.jobId}`,
   408|      'STATUS:\nBLOCKED',
   409|      'FILES CHANGED:\n(none — requires owner confirmation before execution)',
   410|      'COMMANDS:\nNONE — guarded action halted before repo inspection.',
   411|      'TESTS:\nNOT VERIFIED — tests were not run.',
   412|      'DEPLOYED PROOF:\nNONE — owner confirmation required.',
   413|    ].join('\n\n');
   414|  }
   415|
   416|  // Job still running — show live progress from the real queue state.
   417|  // DEFECT FIX (cert-3B): a job whose status is a terminal value (completed/failed/blocked/canceled)
   418|  // must NOT render "RUNNING (...)" even if result is momentarily null (race between status flip
   419|  // and result attachment). Render an honest terminal-pending block instead.
   420|  const TERMINAL_JOB_STATUSES = new Set(['completed', 'failed', 'blocked', 'canceled', 'cancelled']);
   421|  const isTerminalJobStatus = TERMINAL_JOB_STATUSES.has(job.status);
   422|  if (!result && isTerminalJobStatus) {
   423|    return [
   424|      `TASK ID:\n${job.jobId}`,
   425|      `STATUS:\n${job.status.toUpperCase()} (finalizing evidence — poll the status URL)`,
   426|      'FILES CHANGED:\n(evidence being assembled)',
   427|      `COMMANDS:\n- $ worker phase ${job.stage} -> exit pending (status=${job.status}, progress=${job.progressPercent}%)`,
   428|      'TESTS:\nNOT VERIFIED — evidence is being assembled.',
   429|      `DEPLOYED PROOF:\nLive status from durable queue. stage=${job.stage} status=${job.status} progress=${job.progressPercent}% detail="${job.stageDetail}" attempts=${job.attempts}`,
   430|    ].join('\n\n');
   431|  }
   432|  if (!result || job.status === 'queued' || job.status === 'running'
   433|      || job.status === 'patching' || job.status === 'testing'
   434|      || job.status === 'committing' || job.status === 'deploying'
   435|      || job.status === 'verifying') {
   436|    return [
   437|      `TASK ID:\n${job.jobId}`,
   438|      `STATUS:\nRUNNING (${job.status}, ${job.progressPercent}%)`,
   439|      'FILES CHANGED:\n(inspection in progress)',
   440|      `COMMANDS:\n- $ worker phase ${job.stage} -> exit pending (stage: ${job.stage}, progress: ${job.progressPercent}%)`,
   441|      'TESTS:\nNOT VERIFIED — tests are still running.',
   442|      `DEPLOYED PROOF:\nLive progress from durable queue. stage=${job.stage} progress=${job.progressPercent}% detail="${job.stageDetail}" attempts=${job.attempts}`,
   443|    ].join('\n\n');
   444|  }
   445|
   446|  const taskType = result.taskType ?? classifyTaskType(job.input.goal);
   447|  const validation = validateCompletion(buildEvidenceFromWorkerResult(result));
   448|  const validatedStatus = renderValidatorVerdict(validation.verdict);
   449|  const status = validation.ok ? 'VERIFIED' : validatedStatus;
   450|
   451|  return [
   452|    `TASK ID:\n${job.jobId}`,
   453|    `STATUS:\n${status}`,
   454|    `FILES CHANGED:\n${buildWorkerFilesChangedLine(result, taskType)}`,
   455|    `COMMANDS:\n${buildWorkerCommandsSection(job, result)}`,
   456|    `TESTS:\n${buildWorkerTestsSection(result)}`,
   457|    `DEPLOYED PROOF:\n${buildWorkerDeployedProofSection(job, result, status)}`,
   458|    buildNarrativeAppendix(result, validation.verdict),
   459|  ].filter((section) => section.length > 0).join('\n\n');
   460|}

